// @vitest-environment node
import { test, before, after, afterEach } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { http, HttpResponse } from 'msw'
import { setupServer } from 'msw/node'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

const pricingApi = 'http://pricing.test'
const prices = { APPLE: 10, TV: 60 }
const pricingMock = setupServer(
  http.get(`${pricingApi}/prices/:sku`, ({ params }) => HttpResponse.json({ price: prices[params.sku] })),
)
let server, base

before(async () => {
  pricingMock.listen({ onUnhandledRequest: 'bypass' })
  server = createServer(createApp({ pricing: createPricingClient(pricingApi) }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
afterEach(() => pricingMock.resetHandlers())
after(async () => {
  pricingMock.close()
  await new Promise((r) => server.close(r))
})

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })

test('POST /orders creates an order, priced via pricing service, 201', async () => {
  const res = await post({ items: [{ sku: 'APPLE', qty: 3 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'APPLE', qty: 3 }], total: 30 })
  assert.match(body.id, /^\d+$/)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const body = await (await post({ items: [{ sku: 'APPLE', qty: 10 }] })).json()
  assert.equal(body.total, 100)
})

test('POST /orders: total above 100 gets 10% discount', async () => {
  const body = await (await post({ items: [{ sku: 'TV', qty: 2 }] })).json()
  assert.equal(body.total, 108)
})

test('POST /orders: total is floored (truncated) to whole euros', async () => {
  pricingMock.use(http.get(`${pricingApi}/prices/:sku`, () => HttpResponse.json({ price: 10.99 })))
  const body = await (await post({ items: [{ sku: 'X', qty: 1 }] })).json()
  assert.equal(body.total, 10)
})

test('POST /orders: ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'APPLE', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'APPLE', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders: sums multiple items and encodes sku in pricing call', async () => {
  const seen = []
  pricingMock.use(http.get(`${pricingApi}/prices/:sku`, ({ params }) => {
    seen.push(params.sku)
    return HttpResponse.json({ price: 5 })
  }))
  const body = await (await post({ items: [{ sku: 'a b', qty: 1 }, { sku: 'c', qty: 2 }] })).json()
  assert.equal(body.total, 15)
  assert.deepEqual(seen, ['a b', 'c'])
})

test('POST /orders: missing items, empty items, non-array items => 400', async () => {
  for (const b of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(b)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders: invalid JSON => 400', async () => {
  const res = await post(null, '{nope')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('POST /orders: empty body => 400', async () => {
  const res = await post(null, '')
  assert.equal(res.status, 400)
})

test('POST /orders: unknown sku (pricing gives no price) => 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — price undefined yields NaN, serialised as null; order is still created
  const res = await post({ items: [{ sku: 'NOPE', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('GET /orders/:id returns a created order', async () => {
  const created = await (await post({ items: [{ sku: 'TV', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for unknown id => 200 {error:not found}', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is answered with 200, not 404
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods => 404 {error:no route}', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/x']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
